#include <stdio.h>
#include <string.h>

int findLUSlength(const char *a, const char *b) {
    if (strcmp(a, b) == 0) return -1;
    size_t la = strlen(a), lb = strlen(b);
    return (int)(la > lb ? la : lb);
}

